		_allDefinitions.Add(new TerminalSettingDef("EventAndRebellionApiThinkingEnabled", "AI核心", "1. AI 核心配置/4. 事件与王国叛乱API（周报生成与叛乱命名）", "开启思维链", "默认关闭。事件周报与王国叛乱命名是严格格式任务，建议只在确认接口会把最终答案稳定写入 content 时开启。开启后，对 OpenAI 兼容思考接口写入 thinking.type=enabled，并写入 reasoning_effort；Anthropic/Claude 接口写入 thinking.type=enabled 与 output_config.effort。关闭后写入 thinking.type=disabled。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EventAndRebellionApiThinkingEnabled, (s, v) => s.EventAndRebellionApiThinkingEnabled = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EventAndRebellionApiReasoningEffortDropdown", "AI核心", "1. AI 核心配置/4. 事件与王国叛乱API（周报生成与叛乱命名）", "思维链强度", "支持 minimal/low/medium/high/xhigh/max。关闭“开启思维链”即可关闭思考；YJ Gemini 使用原值发送。", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.EventAndRebellionApiReasoningEffortDropdown?.SelectedValue ?? "", (s, v) => { if (s.EventAndRebellionApiReasoningEffortDropdown != null && v is int idx && idx >= 0 && idx < s.EventAndRebellionApiReasoningEffortDropdown.Count) { var dd = s.EventAndRebellionApiReasoningEffortDropdown; dd.SelectedIndex = idx; s.EventAndRebellionApiReasoningEffortDropdown = dd; } }, null, s => s.EventAndRebellionApiReasoningEffortDropdown));
		_allDefinitions.Add(new TerminalSettingDef("EventAndRebellionApiTemperature", "AI核心", "1. AI 核心配置/4. 事件与王国叛乱API（周报生成与叛乱命名）", "温度", "控制事件周报与王国叛乱命名的随机性。0 更稳定，2 更发散。默认 0.80。", TerminalSettingType.FloatingInteger, 0f, 2f, 0.05f, "0.00", s => s.EventAndRebellionApiTemperature, (s, v) => s.EventAndRebellionApiTemperature = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("EventAndRebellionApiMaxTokens", "AI核心", "1. AI 核心配置/4. 事件与王国叛乱API（周报生成与叛乱命名）", "最大输出Tokens", "事件周报、王国叛乱建国命名与统治者政策生成调用的 max_tokens。默认 12000；如果接口不支持过高上限，可能会被接口拒绝。", TerminalSettingType.Integer, 512f, 64000f, 1f, "0", s => s.EventAndRebellionApiMaxTokens, (s, v) => s.EventAndRebellionApiMaxTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("GuardrailDirectTopN", "AI核心", "6. 规则触发（返回）", "规则返回上限", "控制每次对话最多向 AI 提供多少条附加规则。系统会自动推导召回和精排数量；若实际高相关规则不足，不会为了凑数硬塞。默认 4。", TerminalSettingType.Integer, 1f, 12f, 1f, "0", s => s.GuardrailDirectTopN, (s, v) => s.GuardrailDirectTopN = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("KnowledgeDirectTopN", "AI核心", "5. 知识检索（返回）", "知识返回上限", "控制每次对话最多向 AI 提供多少条相关知识。系统按重要性顺序取最靠前的同等数量名词，每个名词独立占一个知识槽；若最高分知识已被前面的名词占用，则顺延到第一条未占用知识。只有上限大于名词数时，才额外补充各名词的后续结果。默认 4。", TerminalSettingType.Integer, 1f, 12f, 1f, "0", s => s.KnowledgeDirectTopN, (s, v) => s.KnowledgeDirectTopN = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldEntityInjectMaxCount", "AI核心", "5. 知识检索（返回）", "实体注入上限", "控制每次对话最多向 AI 注入多少个人物、地点、家族和王国检索结果。系统按前处理的重要性顺序让每个名词先占一个最高分实体槽；重名人物会优先采用其他名词明确限定的家族、其次采用王国，再按其与当前聊天 NPC 的实际大地图距离获得最高 0.15 的微量加分，最终分允许超过 1.00；范围或位置不可用时回退原始得分。若最高分实体已被前面的名词占用，则顺延到第一条未占用实体。只有上限大于名词数时才补次要结果：先为最靠前名词补最多 3 条，再依次处理后续名词。默认 6。", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.WorldEntityInjectMaxCount, (s, v) => s.WorldEntityInjectMaxCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PromptListCandidateMaxCount", "AI核心", "5. 知识检索（返回）", "清单候选显示上限", "控制每类物品、装备、部队、俘虏、固定资产和政策候选向 AI 注入多少条；候选足够时会补满到该数量，候选不足则显示全部。默认 10；不影响人物、地点、家族、王国的实体注入上限。", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.PromptListCandidateMaxCount, (s, v) => s.PromptListCandidateMaxCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("DailyConversationHistoryLineLimit", "AI核心", "5. 压缩记忆", "日内聊天上下文条数", "控制信使、自由对话和场景喊话每次请求最多直接携带多少条尚未日结压缩的普通聊天历史。AFEF 事实不占此额度；不会限制玩家继续聊天，也不会删除每日原始记忆。数值越高，单次请求 token 与等待时间通常越高。默认 100，最低 10，最高 500。", TerminalSettingType.Integer, 10f, 500f, 1f, "0", s => s.DailyConversationHistoryLineLimit, (s, v) => s.DailyConversationHistoryLineLimit = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryCompressionDenominator", "AI核心", "5. 压缩记忆", "记忆压缩比例分母", "日结摘要目标字数为当天有效对话总字数的 1/N，默认 5。AFEF 行不计入总字数且不会被压缩；摘要最少 80 字。", TerminalSettingType.Integer, 3f, 10f, 1f, "0", s => s.MemoryCompressionDenominator, (s, v) => s.MemoryCompressionDenominator = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemorySummaryRequestsPerMinute", "AI核心", "5. 压缩记忆", "记忆总结 RPM", "跨天后每分钟最多并发总结多少个 NPC/日记忆。默认 3，最高 20。", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.MemorySummaryRequestsPerMinute, (s, v) => s.MemorySummaryRequestsPerMinute = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryCandidateLimit", "AI核心", "5. 压缩记忆", "记忆候选上限", "进入前处理的压缩记忆候选块数量。默认 20；15-20 通常最合适。超过该数量时使用富标题语义检索。", TerminalSettingType.Integer, 5f, 40f, 1f, "0", s => s.MemoryCandidateLimit, (s, v) => s.MemoryCandidateLimit = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryFinalInjectCount", "AI核心", "5. 压缩记忆", "最终注入记忆数", "主链路最终注入的压缩记忆块数量。默认 4；运行时不会超过“记忆候选上限”。", TerminalSettingType.Integer, 2f, 20f, 1f, "0", s => s.MemoryFinalInjectCount, (s, v) => s.MemoryFinalInjectCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryPreprocessMode", "AI核心", "5. 压缩记忆", "前处理模式", "1=同体模式：规则 Code 与记忆编号放进同一个前处理 JSON 请求；2=并发模式：规则筛选与记忆筛选同时请求，全部成功解析后进入主链路。默认 1。", TerminalSettingType.Integer, 1f, 2f, 1f, "0", s => s.MemoryPreprocessMode, (s, v) => s.MemoryPreprocessMode = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryOverviewStartBlockCount", "AI核心", "5. 压缩记忆", "记忆大总结启动块数", "当某个 Hero NPC 的压缩记忆块达到该数量后，后台生成并滚动更新“过往记忆总览”。默认 5。", TerminalSettingType.Integer, 3f, 10f, 1f, "0", s => s.MemoryOverviewStartBlockCount, (s, v) => s.MemoryOverviewStartBlockCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryOverviewTargetChars", "AI核心", "5. 压缩记忆", "记忆大总结目标字数", "控制“过往记忆总览”的目标中文字符数。默认 200；越短越省 token，越长越保留细节。", TerminalSettingType.Integer, 100f, 1000f, 1f, "0", s => s.MemoryOverviewTargetChars, (s, v) => s.MemoryOverviewTargetChars = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableTtsSpeech", "AI核心", "7. 火山引擎 TTS（专用）", "启用TTS语音", "总开关。关闭后，NPC 不再播放 TTS 语音，并回退到纯文本气泡显示。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableTtsSpeech, (s, v) => s.EnableTtsSpeech = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedEnabled", "AI核心", "7. 火山引擎 TTS（专用）", "启用火山专用模式", "开启后，TTS 请求将走火山 V1 HTTP 非流式原生协议（Authorization: Bearer;token + app/user/audio/request 结构）。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.TtsVolcDedicatedEnabled, (s, v) => s.TtsVolcDedicatedEnabled = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedApiUrl", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用 API 地址", "V1 非流式地址: https://openspeech.bytedance.com/api/v1/tts", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedApiUrl ?? "", (s, v) => s.TtsVolcDedicatedApiUrl = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedApiKey", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用 Token (Authorization Bearer)", "请求头将按文档写入：Authorization: Bearer;{token}", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedApiKey ?? "", (s, v) => s.TtsVolcDedicatedApiKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedAppKey", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用 AppID", "即 V1 请求体 app.appid。", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedAppKey ?? "", (s, v) => s.TtsVolcDedicatedAppKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedResourceId", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用 Resource ID", "写入请求头 X-Api-Resource-Id。\\n可填：seed-tts-1.0 / seed-tts-1.0-concurr / seed-tts-2.0 / seed-icl-1.0 / seed-icl-1.0-concurr / seed-icl-2.0", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedResourceId ?? "", (s, v) => s.TtsVolcDedicatedResourceId = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedSpeaker", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用 voice_type", "示例: zh_male_M392_conversation_wvae_bigtts", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedSpeaker ?? "", (s, v) => s.TtsVolcDedicatedSpeaker = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedAdditionsJson", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用 extra_param(JSON对象)", "将原样写入 request.extra_param（字符串）。示例：{\\", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedAdditionsJson ?? "", (s, v) => s.TtsVolcDedicatedAdditionsJson = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedAudioFormat", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用音频格式", "V1 encoding，当前播放器仅支持 wav 或 pcm。", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedAudioFormat ?? "", (s, v) => s.TtsVolcDedicatedAudioFormat = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedSampleRate", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用采样率", "V1 rate 建议填 8000 / 16000 / 24000。", TerminalSettingType.Integer, 8000f, 24000f, 1f, "0", s => s.TtsVolcDedicatedSampleRate, (s, v) => s.TtsVolcDedicatedSampleRate = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedVolume", "AI核心", "7. 火山引擎 TTS（专用）", "主语音音量(winmm)", "仅用于普通对话/测试语音（agentIndex<0）的主播放链路。场景喊话口型链路请调“口型链路音量”。", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.TtsVolcDedicatedVolume, (s, v) => s.TtsVolcDedicatedVolume = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedSpeed", "AI核心", "7. 火山引擎 TTS（专用）", "火山专用语速", "V1 speed_ratio，范围 [0.1, 2.0]。", TerminalSettingType.FloatingInteger, 0.1f, 2f, 0.05f, "0.00", s => s.TtsVolcDedicatedSpeed, (s, v) => s.TtsVolcDedicatedSpeed = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsSceneUseWinmmAudible", "AI核心", "7. 火山引擎 TTS（专用）", "场景发声走winmm(防回声)", "开启：场景NPC由winmm发声，口型链路仅驱动嘴型并静音。关闭：场景NPC改由口型链路发声，可调“口型链路音量”。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.TtsSceneUseWinmmAudible, (s, v) => s.TtsSceneUseWinmmAudible = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsLipSyncSoundEventVolume", "AI核心", "7. 火山引擎 TTS（专用）", "口型链路音量", "用于 Rhubarb 口型驱动的 SoundEvent 音量。仅当“场景发声走winmm(防回声)”关闭时作为场景可听音量。", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.TtsLipSyncSoundEventVolume, (s, v) => s.TtsLipSyncSoundEventVolume = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TestTtsVolcDedicatedVoice", "AI核心", "7. 火山引擎 TTS（专用）", "测试语音", "使用火山 V1 原生参数测试固定文本「为您服务，旅行者！」", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.TestTtsVolcDedicatedVoice?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EnableDeepTrace", "AI核心", "4. 开发者选项", "【开发者】开启全代码截获", "⚠\\ufe0f 极其硬核的调试功能！\\n开启后将截获所有 UI 点击、状态切换和底层代码堆栈(Trace)。\\n日志量极大，仅供开发者排查问题使用。普通玩家请勿开启！", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDeepTrace, (s, v) => s.EnableDeepTrace = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableDevEditHistory", "AI核心", "4. 开发者选项", "【开发者】启用数据管理（对话历史/赊账/个性/玩家履历）", "开启后，城镇主菜单中会出现【开发】数据管理入口，用于查看和修改任意 NPC 的历史对话记录、赊账/欠款、个性背景等数据；角色(C)中的玩家知名度/履历弹窗也会开放玩家履历编辑。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDevEditHistory, (s, v) => s.EnableDevEditHistory = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableAdultHeroPersonaAutoGeneration", "AI核心", "4. 开发者选项", "新成年人物自动生成个性与背景", "开启后，当英雄子女成年时，自动使用前处理API为其生成个性与历史背景。已有个性或背景不会被覆盖。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableAdultHeroPersonaAutoGeneration, (s, v) => s.EnableAdultHeroPersonaAutoGeneration = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableModLogicLog", "AI核心", "4. 开发者选项", "【日志】写入 Mod_Logic.txt", "总逻辑日志开关。关闭后不再写入 Mod_Logic.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableModLogicLog, (s, v) => s.EnableModLogicLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableVerboseModLogicLog", "AI核心", "4. 开发者选项", "【日志】写入详细调试日志", "只在排查问题时开启。开启后会写入更细的 Mod_Logic 诊断日志；大型剧本大地图可能产生较多日志。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableVerboseModLogicLog, (s, v) => s.EnableVerboseModLogicLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableObservabilityLog", "AI核心", "4. 开发者选项", "【日志】写入 Observability.jsonl", "结构化观测日志开关。关闭后不再写入 Observability.jsonl。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableObservabilityLog, (s, v) => s.EnableObservabilityLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableHitRateStatsLog", "AI核心", "4. 开发者选项", "【日志】写入 HitRate_Stats.txt", "命中率统计日志开关。关闭后不再写入 HitRate_Stats.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableHitRateStatsLog, (s, v) => s.EnableHitRateStatsLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableTokenStatsLog", "AI核心", "4. 开发者选项", "【日志】写入 Token_Stats.txt", "Token 统计日志开关。关闭后不再写入 Token_Stats.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableTokenStatsLog, (s, v) => s.EnableTokenStatsLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableEventLogs", "AI核心", "4. 开发者选项", "【日志】写入 Event_Logs.txt", "事件系统周报生成日志开关。关闭后不再写入 Event_Logs.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableEventLogs, (s, v) => s.EnableEventLogs = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnablePerformanceMonitor", "AI核心", "4. 开发者选项", "【性能】启用性能监控", "开启后每30秒向 Mod_Logic.txt 写入 FPS、慢帧和帧总耗时。只有同时开启详细调试日志时才采集各 Tick/Scope 耗时；普通游玩不承担逐 Scope 统计成本。默认关闭。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePerformanceMonitor, (s, v) => s.EnablePerformanceMonitor = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableDeferredDailyMaintenance", "AI核心", "4. 开发者选项", "【性能】延后日结维护", "开启后，每日结算只登记 AnimusForge 维护任务，记忆总览、王国维护和周报准备会在后续大地图中按单帧预算分批执行。维护会在每个大地图 Tick 推进，不因行军暂停。默认开启。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDeferredDailyMaintenance, (s, v) => s.EnableDeferredDailyMaintenance = Convert.ToBoolean(v)));
