		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyDeclarationMaxCharacters", "外交与国家", "17. AI外交（测试中）", "外交宣言最大字数", "AI 生成的外交宣言正文最多使用多少个中文字符，标点计入。默认 200；可在 1—1000 之间调整；若小于最小字数，运行时按最小字数处理。", TerminalSettingType.Integer, 1f, 1000f, 1f, "0", s => s.WorldDiplomacyDeclarationMaxCharacters, (s, v) => s.WorldDiplomacyDeclarationMaxCharacters = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyOffensiveWarCooldownDays", "外交与国家", "17. AI外交（测试中）", "再次主动开战间隔（天）", "一个国家主动发动战争后，至少等待多少天才能再次主动发动新战争。默认 42 天。", TerminalSettingType.Integer, 7f, 120f, 1f, "0", s => s.WorldDiplomacyOffensiveWarCooldownDays, (s, v) => s.WorldDiplomacyOffensiveWarCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyPeaceProtectionDays", "外交与国家", "17. AI外交（测试中）", "和平保护期（天）", "两国议和后，在这段时间内不会因为普通外交争端再次开战。默认 21 天。", TerminalSettingType.Integer, 0f, 60f, 1f, "0", s => s.WorldDiplomacyPeaceProtectionDays, (s, v) => s.WorldDiplomacyPeaceProtectionDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyTradeAllianceFailedProposalCooldownDays", "外交与国家", "17. AI外交（测试中）", "贸易/结盟失败冷却（天）", "贸易或结盟提议未达成后，同一提出国→同一对象国在这段时间内不能再次发起相同类型提议；反向提议和另一类型互不影响。默认 168 天；设为 0 关闭。", TerminalSettingType.Integer, 0f, 672f, 1f, "0", s => s.WorldDiplomacyTradeAllianceFailedProposalCooldownDays, (s, v) => s.WorldDiplomacyTradeAllianceFailedProposalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyThreatComplianceIssuerRelationReward", "外交与国家", "17. AI外交（测试中）", "威慑退让国内关系奖励", "对象国明确服从谴责或最后通牒后，发出国每个正式、非雇佣兵封臣家族的族长与当前国王关系增加此数值。每次威慑只结算一次；设为 0 关闭。", TerminalSettingType.Integer, 0f, 50f, 1f, "0", s => s.WorldDiplomacyThreatComplianceIssuerRelationReward, (s, v) => s.WorldDiplomacyThreatComplianceIssuerRelationReward = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyHistoryCompressionTriggerThousands", "外交与国家", "17. AI外交（测试中）", "外交长期记忆压缩触发值（千估算 Tokens）", "长期外交历史达到该估算长度时开始压缩。默认 800，即约 800k Tokens；阈值越高，每次外交请求的延迟与费用通常越高。所选 API 模型必须有足够输入上下文，900k 仅适合上下文明显大于 1M 的模型。", TerminalSettingType.Integer, 64f, 900f, 1f, "0", s => s.WorldDiplomacyHistoryCompressionTriggerThousands, (s, v) => s.WorldDiplomacyHistoryCompressionTriggerThousands = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyHistoryCompressionTargetThousands", "外交与国家", "17. AI外交（测试中）", "外交长期记忆压缩后目标（千估算 Tokens）", "压缩完成后，长期外交快照与程序保留的近期硬事实合计目标长度。默认 48，即约 48k Tokens；上限 60k。实际摘要仍受所选 API 的“最大输出Tokens”限制，该上限较低时会生成更短快照。", TerminalSettingType.Integer, 8f, 60f, 1f, "0", s => s.WorldDiplomacyHistoryCompressionTargetThousands, (s, v) => s.WorldDiplomacyHistoryCompressionTargetThousands = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EditWorldDiplomacyPrompt", "外交与国家", "17. AI外交（测试中）", "AI外交自定义偏好", "编辑利益判断、行动取向与文风偏好。留空表示不添加偏好；固定共同契约、事实边界和 MODE 输出规则不会被覆盖。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditWorldDiplomacyPrompt?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("RestoreDefaultWorldDiplomacyPrompt", "外交与国家", "17. AI外交（测试中）", "恢复默认AI外交偏好", "弹出确认后，将自定义偏好恢复为模组默认内容。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.RestoreDefaultWorldDiplomacyPrompt?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EnableNobleGathering", "外交与国家", "18. 宴会功能", "启用宴会功能", "宴会系统总开关。关闭后停止创建新宴会，正在进行的宴会会在下一个安全的战役小时结算为取消，并安排主人和宾客返程；无需重启游戏。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNobleGathering, (s, v) => s.EnableNobleGathering = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNpcAutomaticNobleGatherings", "外交与国家", "18. 宴会功能", "启用NPC自动举办宴会", "开启后，符合条件的 NPC 会按王国自动举办宴会。关闭后不再自动创建 NPC 宴会，但玩家仍可主动举办。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcAutomaticNobleGatherings, (s, v) => s.EnableNpcAutomaticNobleGatherings = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("AllowNpcNobleGatheringPlayerInvitations", "外交与国家", "18. 宴会功能", "允许NPC邀请玩家", "开启后，NPC 宴会可以邀请玩家并派信使送信。关闭后只阻止新邀请，已经发出的玩家邀请仍然有效。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AllowNpcNobleGatheringPlayerInvitations, (s, v) => s.AllowNpcNobleGatheringPlayerInvitations = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShowNobleGatheringGuestArrivalMessages", "外交与国家", "18. 宴会功能", "显示宾客抵达提示", "控制玩家举办宴会时宾客抵达后的左下角彩色消息。关闭后只隐藏提示，不影响抵达判定、宴会状态或奖励。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.ShowNobleGatheringGuestArrivalMessages, (s, v) => s.ShowNobleGatheringGuestArrivalMessages = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcNobleGatheringIntervalDays", "外交与国家", "18. 宴会功能", "NPC宴会间隔（天）", "同一王国两次自动宴会排期之间的游戏天数，默认 21 天。按王国分别计算；修改后用于下一次重新排期。", TerminalSettingType.Integer, 7f, 120f, 1f, "0", s => s.NpcNobleGatheringIntervalDays, (s, v) => s.NpcNobleGatheringIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("AllowNpcNobleGatheringGovernorInvitations", "外交与国家", "18. 宴会功能", "NPC可以邀请总督", "只影响 NPC 自动生成的宾客名单。关闭时 NPC 不会邀请正在治理定居点的总督；玩家举办宴会时仍可自由邀请总督。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AllowNpcNobleGatheringGovernorInvitations, (s, v) => s.AllowNpcNobleGatheringGovernorInvitations = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringDurationDays", "外交与国家", "18. 宴会功能", "宴会持续天数", "玩家与 NPC 宴会共用，默认 5 天。修改只影响之后新创建的宴会，已经开始的宴会保持原结束日期。", TerminalSettingType.Integer, 1f, 14f, 1f, "0", s => s.NobleGatheringDurationDays, (s, v) => s.NobleGatheringDurationDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringCost", "外交与国家", "18. 宴会功能", "宴会举办费用", "玩家与 NPC 主人共用，费用从实际主人身上扣除。默认 50000 第纳尔；设为 0 表示免费。", TerminalSettingType.Integer, 0f, 500000f, 1f, "0", s => s.NobleGatheringCost, (s, v) => s.NobleGatheringCost = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringInvitedClanRelationReward", "外交与国家", "18. 宴会功能", "每个受邀家族关系奖励", "玩家与 NPC 宴会共用；主人和每个受邀家族领袖每场只结算一次。默认 5；设为 0 表示不增加关系。修改只影响之后新创建的宴会。", TerminalSettingType.Integer, 0f, 20f, 1f, "0", s => s.NobleGatheringInvitedClanRelationReward, (s, v) => s.NobleGatheringInvitedClanRelationReward = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportLengthPreset", "外交与国家", "12. 事件系统（开发）", "周报篇幅档位", "1=200-400字；2=200-800字；3=200-1200字；4=200-1500字。世界周报和王国周报共用这一档位；默认 2。", TerminalSettingType.Integer, 1f, 4f, 1f, "0", s => s.WeeklyReportLengthPreset, (s, v) => s.WeeklyReportLengthPreset = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportRequestsPerMinute", "外交与国家", "12. 事件系统（开发）", "每分钟最多生成周报数", "限制开发态周报生成的请求速率。默认 5；最高 20。用于应对部分 API 渠道的 RPM 或并发限制。", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.WeeklyReportRequestsPerMinute, (s, v) => s.WeeklyReportRequestsPerMinute = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("AutoGenerateWeeklyReports", "外交与国家", "12. 事件系统（开发）", "每周自动生成周报", "开启后，系统会在每个新周开始时自动结算上一周，并生成世界周报与各王国周报。第0天会自动写入开局概要作为 week 0 事件。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AutoGenerateWeeklyReports, (s, v) => s.AutoGenerateWeeklyReports = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportPopupBodyFontSize", "外交与国家", "12. 事件系统（开发）", "周报弹窗正文字号", "仅影响最近王国周报的大弹窗正文，不影响别的界面。默认 18。", TerminalSettingType.Integer, 12f, 36f, 1f, "0", s => s.WeeklyReportPopupBodyFontSize, (s, v) => s.WeeklyReportPopupBodyFontSize = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWeeklyReportMapNotifications", "外交与国家", "12. 事件系统（开发）", "周报右下角消息提示", "开启后，周报生成完成时会在大地图右下角显示可点击消息；关闭后不显示，且关闭期间新生成的周报不会排队提示。默认开启。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWeeklyReportMapNotifications, (s, v) => s.EnableWeeklyReportMapNotifications = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWeeklyReportReadingXpReward", "外交与国家", "12. 事件系统（开发）", "启用周报阅读经验奖励", "开启后，从地图通知打开周报并停留满 10 秒，会按三栏字数累计经验；每研读 20 篇后一次性给玩家魅力、统御和管理经验。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWeeklyReportReadingXpReward, (s, v) => s.EnableWeeklyReportReadingXpReward = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportReadingXpPerHundredChars", "外交与国家", "12. 事件系统（开发）", "周报每百字经验", "周报阅读奖励的字数倍率。默认 20，表示每栏每 100 个有效字/词给 20 点对应技能经验。", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.WeeklyReportReadingXpPerHundredChars, (s, v) => s.WeeklyReportReadingXpPerHundredChars = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportReadingXpSkillCap", "外交与国家", "12. 事件系统（开发）", "周报单技能经验上限", "单份周报每个技能最多获得多少经验。默认 100；设置为 0 表示不发放周报阅读经验。", TerminalSettingType.Integer, 0f, 500f, 1f, "0", s => s.WeeklyReportReadingXpSkillCap, (s, v) => s.WeeklyReportReadingXpSkillCap = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableKingdomStabilityAndRebellion", "外交与国家", "12. 事件系统（开发）", "启用王国稳定度与叛乱", "关闭后，不再触发本模组的王国叛乱；王国稳定度不会再影响国王直辖领地忠诚度，也不会继续施加稳定度关系修正。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableKingdomStabilityAndRebellion, (s, v) => s.EnableKingdomStabilityAndRebellion = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnablePlayerKingdomRebellionImmunity", "外交与国家", "12. 事件系统（开发）", "玩家为国王时免疫稳定度叛乱", "开启后，当玩家家族是某个王国的执政家族或玩家本人是该王国领袖时，本模组的王国稳定度不会继续给该王国施加关系修正、国王直辖地忠诚修正或王国叛乱判定。原版城镇低忠诚叛乱仍按原版规则运行。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePlayerKingdomRebellionImmunity, (s, v) => s.EnablePlayerKingdomRebellionImmunity = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("GcczNpcResponseUnlimited", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "NPC Response Unlimited", "Removes the configured numeric cap in active GCCZ town scenes while retaining event deduplication and queue safety.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.GcczNpcResponseUnlimited, (s, v) => s.GcczNpcResponseUnlimited = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("GcczNpcResponseLimit", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "NPC Response Limit", "Limits ambient NPC replies per player utterance, semantic action, or player attack event in an active GCCZ town scene.", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.GcczNpcResponseLimit, (s, v) => s.GcczNpcResponseLimit = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableGcczDiagnosticLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "写入 GCCZ 日志", "写入独立的 GCCZ_Debug.log。关闭后停止新增日志，但仍可导出或清空已有日志。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableGcczDiagnosticLog, (s, v) => s.EnableGcczDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableGcczVerboseDiagnosticLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "GCCZ 详细日志", "记录 NPC 回应限额等高频诊断。排查问题时再开启；关闭后仍保留阶段变化、处置结果和异常等关键日志。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableGcczVerboseDiagnosticLog, (s, v) => s.EnableGcczVerboseDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("GcczDiagnosticLogMaxSizeMegabytes", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "GCCZ 日志上限(MB)", "GCCZ_Debug.log 达到上限后自动轮转，上一份保留为 GCCZ_Debug.previous.log。默认 16 MB。", TerminalSettingType.Integer, 1f, 128f, 1f, "0", s => s.GcczDiagnosticLogMaxSizeMegabytes, (s, v) => s.GcczDiagnosticLogMaxSizeMegabytes = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ExportGcczDebugLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "导出 GCCZ_Debug.log", "将当前模块 Logs 文件夹里的 GCCZ_Debug.log 独立复制到桌面，文件名会带时间戳。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ExportGcczDebugLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ClearGcczDebugLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "清空 GCCZ_Debug.log", "只清空当前 GCCZ_Debug.log，不删除上一份轮转日志。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ClearGcczDebugLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EnableSetsDiagnosticLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "写入 SETS 日志", "写入独立的 SETS.log，用于进城随行与内部暴乱诊断。关闭后停止新增日志，但仍可导出或清空已有日志。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableSetsDiagnosticLog, (s, v) => s.EnableSetsDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableSetsVerboseDiagnosticLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "SETS 详细日志", "记录逐帧保护、指挥刷新和刷兵进度等高频诊断。排查卡住时再开启；关闭后仍保留冲突开始、波次、胜利和异常等关键日志。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableSetsVerboseDiagnosticLog, (s, v) => s.EnableSetsVerboseDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("SetsDiagnosticLogMaxSizeMegabytes", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "SETS 日志上限(MB)", "SETS.log 达到上限后自动轮转，上一份保留为 SETS.previous.log。默认 16 MB。", TerminalSettingType.Integer, 1f, 128f, 1f, "0", s => s.SetsDiagnosticLogMaxSizeMegabytes, (s, v) => s.SetsDiagnosticLogMaxSizeMegabytes = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ExportSetsDiagnosticLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "导出 SETS.log", "将当前模块 Logs 文件夹里的 SETS.log 独立复制到桌面，文件名会带时间戳。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ExportSetsDiagnosticLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ClearSetsDiagnosticLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "清空 SETS.log", "只清空当前 SETS.log，不删除上一份轮转日志。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ClearSetsDiagnosticLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ExportNoblePrisonerEscortLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "导出贵族俘虏随行日志", "将 NoblePrisonerEscort.log 独立复制到桌面，用于排查俘虏生成、场景处决与野外会面撤退。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ExportNoblePrisonerEscortLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ClearNoblePrisonerEscortLog", "决斗与部队", "战后与围城限制 (Siege & NPC Limits)", "清空贵族俘虏随行日志", "只清空当前 NoblePrisonerEscort.log，不删除上一份轮转日志。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ClearNoblePrisonerEscortLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("IntimacyPregnancyChancePercent", "角色与同伴", "15. 亲密行为与怀孕", "怀孕几率（%）", "当亲密行为标签确认本轮已发生性行为和内射后，女方怀孕的概率。0 表示不会怀孕，100 表示必定怀孕。默认 50%。", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.IntimacyPregnancyChancePercent, (s, v) => s.IntimacyPregnancyChancePercent = Convert.ToInt32(v)));
